# --- Validation of constraints ---

_jslength(x::AbstractString) = length(x)

function _jsvalidate(x, c, where_::String)
    c === nothing && return nothing
    x === nothing && return nothing
    if x isa Real && !(x isa Bool)
        haskey(c, :minimum) && x < c.minimum && _jsfail("$where_ must be ≥ $(c.minimum), got $x")
        haskey(c, :maximum) && x > c.maximum && _jsfail("$where_ must be ≤ $(c.maximum), got $x")
        haskey(c, :exclusiveMinimum) && x <= c.exclusiveMinimum && _jsfail("$where_ must be > $(c.exclusiveMinimum), got $x")
        haskey(c, :exclusiveMaximum) && x >= c.exclusiveMaximum && _jsfail("$where_ must be < $(c.exclusiveMaximum), got $x")
        if haskey(c, :multipleOf)
            q = x / c.multipleOf
            isapprox(q, round(q); atol = 1e-9) || _jsfail("$where_ must be a multiple of $(c.multipleOf), got $x")
        end
    elseif x isa AbstractString
        haskey(c, :minLength) && _jslength(x) < c.minLength && _jsfail("$where_ must have at least $(c.minLength) characters, got $(repr(x))")
        haskey(c, :maxLength) && _jslength(x) > c.maxLength && _jsfail("$where_ must have at most $(c.maxLength) characters, got $(repr(x))")
        haskey(c, :pattern) && !occursin(c.pattern, x) && _jsfail("$where_ must match the pattern $(c.pattern.pattern), got $(repr(x))")
    elseif x isa AbstractVector
        haskey(c, :minItems) && length(x) < c.minItems && _jsfail("$where_ must have at least $(c.minItems) items, got $(length(x))")
        haskey(c, :maxItems) && length(x) > c.maxItems && _jsfail("$where_ must have at most $(c.maxItems) items, got $(length(x))")
        haskey(c, :uniqueItems) && c.uniqueItems && !allunique(x) && _jsfail("$where_ must have unique items")
        if haskey(c, :items)
            for (i, el) in enumerate(x)
                _jsvalidate(el, c.items, "$where_[$i]")
            end
        end
    elseif x isa AbstractDict
        haskey(c, :minProperties) && length(x) < c.minProperties && _jsfail("$where_ must have at least $(c.minProperties) properties")
        haskey(c, :maxProperties) && length(x) > c.maxProperties && _jsfail("$where_ must have at most $(c.maxProperties) properties")
    end
